const largesseRecipients = `-- name: LargesseRecipients :many
SELECT id FROM app.players
WHERE kingdom_id = $1 AND id <> $2
  AND kingdom_joined_at <= $3::timestamptz AND NOT is_bot
`

type LargesseRecipientsParams struct {
	KingdomID    *uuid.UUID
	Buyer        uuid.UUID
	JoinedBefore time.Time
}

// The members a Largesse reaches: everyone else in the kingdom who has been in
// it long enough.
func (q *Queries) LargesseRecipients(ctx context.Context, arg LargesseRecipientsParams) ([]uuid.UUID, error) {
	rows, err := q.db.Query(ctx, largesseRecipients, arg.KingdomID, arg.Buyer, arg.JoinedBefore)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []uuid.UUID{}
	for rows.Next() {
		var id uuid.UUID
		if err := rows.Scan(&id); err != nil {
			return nil, err
		}
		items = append(items, id)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

