const takeTokens = `-- name: TakeTokens :exec
UPDATE app.player_tokens SET qty = GREATEST(0, qty - $1::bigint)
WHERE player_id = $2 AND token = $3
`

type TakeTokensParams struct {
	Qty      int64
	PlayerID uuid.UUID
	Token    string
}

// Takes back tokens a refunded purchase gave, as far as they are still held.
func (q *Queries) TakeTokens(ctx context.Context, arg TakeTokensParams) error {
	_, err := q.db.Exec(ctx, takeTokens, arg.Qty, arg.PlayerID, arg.Token)
	return err
}

const upsertSubscription = `-- name: UpsertSubscription :one
INSERT INTO app.subscriptions (original_transaction_id, player_id, product_id, environment, status,
                               expires_at, auto_renew, last_transaction_id, updated_at)
VALUES ($1, $2, $3,
        $4, $5, $6, $7,
        $8, now())
ON CONFLICT (original_transaction_id) DO UPDATE
SET status = EXCLUDED.status,
    -- A late notification never winds a subscription back.
    expires_at = GREATEST(app.subscriptions.expires_at, EXCLUDED.expires_at),
    auto_renew = EXCLUDED.auto_renew,
    last_transaction_id = EXCLUDED.last_transaction_id,
    updated_at = now()
RETURNING original_transaction_id, player_id, product_id, environment, status, expires_at, auto_renew, last_transaction_id, updated_at
`

type UpsertSubscriptionParams struct {
	OriginalTransactionID string
	PlayerID              uuid.UUID
	ProductID             string
	Environment           string
	Status                string
	ExpiresAt             time.Time
	AutoRenew             bool
	LastTransactionID     string
}

func (q *Queries) UpsertSubscription(ctx context.Context, arg UpsertSubscriptionParams) (AppSubscription, error) {
	row := q.db.QueryRow(ctx, upsertSubscription,
		arg.OriginalTransactionID,
		arg.PlayerID,
		arg.ProductID,
		arg.Environment,
		arg.Status,
		arg.ExpiresAt,
		arg.AutoRenew,
		arg.LastTransactionID,
	)
	var i AppSubscription
	err := row.Scan(
		&i.OriginalTransactionID,
		&i.PlayerID,
		&i.ProductID,
		&i.Environment,
		&i.Status,
		&i.ExpiresAt,
		&i.AutoRenew,
		&i.LastTransactionID,
		&i.UpdatedAt,
	)
	return i, err
}

const withdrawUnclaimedMail = `-- name: WithdrawUnclaimedMail :execrows
UPDATE app.mail SET deleted_at = $1
WHERE idem_key LIKE $2::text || '%' AND claimed_at IS NULL AND deleted_at IS NULL
`

type WithdrawUnclaimedMailParams struct {
	At     *time.Time
	Prefix string
}

// Takes back the letters a refunded gift sent that nobody opened.
func (q *Queries) WithdrawUnclaimedMail(ctx context.Context, arg WithdrawUnclaimedMailParams) (int64, error) {
	result, err := q.db.Exec(ctx, withdrawUnclaimedMail, arg.At, arg.Prefix)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}
